import Testing

/// Generates every synthetic preset up front. CI runs this suite on its own before the real tests, so encoding
/// (over a minute on a cold runner) never counts against a test's waits or time limit. In a normal run it is
/// harmless: presets already on disk are reused, and ones being generated by other tests are waited for.
@Suite("Synthetic media warm-up")
struct SyntheticMediaWarmupTests {
    @Test("All synthetic presets are generated")
    func generateAllPresets() {
        guard SyntheticTestMediaFactory.ffmpegBinaryPath() != nil else { return }
        for preset in SyntheticTestMediaFactory.Preset.allCases {
            // A preset the local FFmpeg cannot encode is skipped by the tests that use it; not a failure here.
            _ = SyntheticTestMediaFactory.ensureMedia(preset: preset)
        }
    }
}
